typedef unsigned int u_int;
typedef unsigned char u_char;
typedef float sceVu0FVECTOR[4];

class nglVector
{
public:
  float x, y, z, w;
  inline const float& operator[](int i) const { return (&x)[i]; }
  inline float& operator[](int i) { return (&x)[i]; }
  inline operator float*() { return &x; }
  inline operator const float*() { return &x; }
} __attribute__((aligned (16)));

struct nglDebugStruct
{
  u_char ShowPerfInfo, ScreenShot;
  u_char DisableQuads, DisableMeshes, DisableTextures, DisableMipmaps, DisableVSync, DisableScratch, DisableMipOpt;
  u_char DebugPrints, DumpFrameLog, DumpSceneFile, DumpTextures;
  u_char DrawLightSpheres, DrawMeshSpheres, DrawNormals;
  u_char DrawAsPoints, DrawAsLines;
  u_char VUClearMem, VUClearRegs, VUDebugBreak, VUParticleDebugBreak;
  u_char DMARepeatMode;
  u_char DrawToFrontBuffer, SyncRender;
};
extern nglDebugStruct nglSyncDebug;
extern int nglGetClipResultViewOnly( nglVector& Center, float Radius );
extern void* nglListAlloc( u_int Bytes, u_int Alignment = 4 );
extern "C" void sceVu0CopyVector( sceVu0FVECTOR v0, sceVu0FVECTOR v1 );
extern void nglListAddVertexLightNode( u_int Type, void* NodeData, u_int LightCat );
extern void nglDrawDebugSphere( const nglVector& Pos, float Scale, u_int Color, bool Solid );
extern void nglSceneDumpPointLight( u_int Type, u_int LightCat, const nglVector& Pos, float Near, float Far, const nglVector& Color );

#define NGL_RGBA32(r,g,b,a) ((int)((r)+1)>>1) | (((int)((g)+1)>>1)<<8) | (((int)((b)+1)>>1)<<16) | (((int)((a)+1)>>1)<<24)
inline int nglFTOI( float input )
{
  register float output;
  __asm__ volatile ("cvt.w.s %0, %1" : "=f" (output) : "f" (input) );
  return (int&)output;
}
inline u_int nglVectorToColor( const nglVector& Color )
{
  return NGL_RGBA32( nglFTOI( Color[0] * 255.0f ), nglFTOI( Color[1] * 255.0f ), nglFTOI( Color[2] * 255.0f ), nglFTOI( Color[3] * 255.0f ) );
}

struct nglPointLightInfo
{
  nglVector Pos;
  nglVector Color;
  float Near;
  float Far;
};

enum { NGLLIGHT_FAKEPOINT };
#define nglListNew(Type) (Type*)nglListAlloc(sizeof(Type))
#define DEBUG_ENABLE(x) (nglSyncDebug.x)

void nglListAddFakePointLight( u_int LightCat, const nglVector& Pos, float Near, float Far, const nglVector& Color )
{
  if ( nglGetClipResultViewOnly( (nglVector&)Pos, Far ) == -1 )
    return;

  nglPointLightInfo* Light = nglListNew( nglPointLightInfo );
  if ( !Light )
    return;

  sceVu0CopyVector( Light->Pos, (nglVector)Pos );
  Light->Pos[3] = 1.0f;
  Light->Near = Near;
  Light->Far = Far;
  sceVu0CopyVector( Light->Color, (nglVector)Color );

  nglListAddVertexLightNode( NGLLIGHT_FAKEPOINT, Light, LightCat );

  if ( DEBUG_ENABLE( DrawLightSpheres ) )
  {
    u_int col = nglVectorToColor( Light->Color );
    nglDrawDebugSphere( Light->Pos, 0.25f, col, true );
    nglDrawDebugSphere( Light->Pos, Light->Near, col, false );
    nglDrawDebugSphere( Light->Pos, Light->Far, col, false );
  }

  if ( DEBUG_ENABLE( DumpSceneFile ) )
    nglSceneDumpPointLight( NGLLIGHT_FAKEPOINT, LightCat, Pos, Near, Far, Color );
}
